import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'
import type { ActiveAgent, Milestone, PhaseId, PhaseState, Plan, SessionTask, TaskFlash, TaskStatus } from '../types'
import type { EngineInterface } from 'claude-code'
import { parsePlan } from './lib/planParser'
import { buildRoadmapFor, keepLiveAgents, matchTask, newlyCompleted, stampTodos, todosNewlyCompleted } from './lib/taskMatcher'
import { agentTask, CLOSED_SHOW_MS, FLASH_MS, metroBand } from './lib/metro'
import { MILESTONE_MS } from './lib/clawd'
import { EMPTY_PHASE, PHASES, SPEC_RE, advance, isCloseCommand, phaseForSkill, specTitleFrom } from './lib/phases'
import { PALETTE } from './lib/palette'
import { progressBar, visibleRows } from './lib/summary'
import { completedFromLedger, isLedgerFile, ledgerPath, touchesLedgerCommand } from './lib/ledger'
import { PLAN_RE, absolutePath, cdTarget, planDir, planRefsInCommand, repoFromGit, repoRoot, storeKey } from './lib/state'

const tasks = atom({ plugin: 'roadmap', key: 'tasks' } as const, [] as SessionTask[])
const todos = atom({ plugin: 'roadmap', key: 'todos' } as const, [] as SessionTask[])
const agents = atom({ plugin: 'roadmap', key: 'agents' } as const, [] as ActiveAgent[])
const planPath = atom({ plugin: 'roadmap', key: 'planPath' } as const, null as string | null)
const pinned = atom({ plugin: 'roadmap', key: 'pinned' } as const, false)
const plan = atom({ plugin: 'roadmap', key: 'plan' } as const, null as Plan | null)
const planError = atom({ plugin: 'roadmap', key: 'planError' } as const, null as string | null)
const doneStored = atom({ plugin: 'roadmap', key: 'doneStored' } as const, [] as number[])
const isOpen = atom({ plugin: 'roadmap', key: 'isOpen' } as const, false)
const storeOk = atom({ plugin: 'roadmap', key: 'storeOk' } as const, true)
const tick = atom({ plugin: 'roadmap', key: 'tick' } as const, 0)
const phase = atom({ plugin: 'roadmap', key: 'phase' } as const, EMPTY_PHASE as PhaseState)
const milestone = atom({ plugin: 'roadmap', key: 'milestone' } as const, null as Milestone | null)
const flash = atom({ plugin: 'roadmap', key: 'flash' } as const, null as TaskFlash | null)
const repo = atom({ plugin: 'roadmap', key: 'repo' } as const, null as { worktree: string; branch: string } | null)
const bandHidden = atom({ plugin: 'roadmap', key: 'bandHidden' } as const, false)

// El motor sigue `$` solo dentro de funciones declaradas en este mismo fichero.
type Eng = EngineInterface

// Worktree y rama del plan activo (la carpeta del plan, no el cwd de la sesión). Cualquier fallo -> null.
async function refreshRepo($: Eng): Promise<void> {
  try {
    const path = await read($, planPath)
    const source = (await read($, phase)).source
    // sin plan: la carpeta del spec y, si tampoco hay, el cwd de la sesión
    const dir = path ? planDir(path) : source ? planDir(source) : await $.session.cwd()
    const git = async (...args: string[]) => {
      const r = await $.process.run(['git', '-C', dir, ...args])
      return r.exitCode === 0 ? r.stdout : null
    }
    const top = await git('rev-parse', '--show-toplevel')
    let branch = top === null ? null : await git('branch', '--show-current')
    let sha = ''
    if (top !== null && branch !== null && !branch.trim()) sha = (await git('rev-parse', '--short', 'HEAD')) ?? ''
    const found = top === null || branch === null ? null : repoFromGit(top, branch, sha)
    await update($, repo, () => found)
  } catch {
    try {
      await update($, repo, () => null)
    } catch {
      // nunca romper la sesión
    }
  }
}

async function loadPlan($: Eng, path: string): Promise<void> {
  const abs = absolutePath(await $.session.cwd(), path)
  try {
    const parsed = parsePlan(await $.fs.read(abs))
    await update($, plan, () => parsed ?? null)
    await update($, planError, () => (parsed ? null : 'plan no legible'))
  } catch {
    await update($, plan, () => null)
    await update($, planError, () => 'plan no legible')
  }
  try {
    const stored = await $.store.get(storeKey(abs))
    await update($, doneStored, () => (Array.isArray(stored) ? stored.filter(n => typeof n === 'number') : []))
    await update($, storeOk, () => true)
  } catch {
    // sin lectura no se escribe: no se pisa el progreso real guardado (spec §10)
    await update($, doneStored, () => [])
    await update($, storeOk, () => false)
  }
  // la ruta se fija la última: ningún refresh concurrente mezcla planes
  await update($, planPath, () => abs)
  await refreshRepo($)
  await syncLedger($)
}

// Incorpora las Ns nuevas como hechas: estado, almacén, destello y, con el plan entero hecho en impl, revisión.
async function markDone($: Eng, current: Plan, path: string, fresh: number[]): Promise<void> {
  if (fresh.length === 0) return
  // el plan activo pudo cambiar mientras tanto: no se escribe en otro plan
  if ((await read($, planPath)) !== path || JSON.stringify(await read($, plan)) !== JSON.stringify(current)) return
  let merged: number[] = []
  let added: number[] = []
  await update($, doneStored, s => {
    added = fresh.filter((n, i) => !s.includes(n) && fresh.indexOf(n) === i)
    merged = added.length > 0 ? [...s, ...added] : s
    return merged
  })
  if (added.length === 0) return
  const stamp = { n: added[added.length - 1]!, at: await nowMs($) }
  await update($, flash, () => stamp)
  ensureTicker($)
  if (await read($, storeOk)) {
    try {
      await $.store.set(storeKey(path), merged)
    } catch {
      // sin persistencia: se sigue en memoria
    }
  }
  // plan entero hecho en implementación -> revisión
  const everything = [...(await read($, tasks)), ...(await read($, todos))]
  const r = buildRoadmapFor(current, everything, merged, path)
  if (r.total > 0 && r.done === r.total && (await read($, phase)).current === 'impl') await advancePhase($, 'review')
}

// Lee el ledger SDD del plan activo y marca las Tasks completas que aún no constan.
async function syncLedger($: Eng): Promise<void> {
  try {
    const current = await read($, plan)
    const path = await read($, planPath)
    if (!current || !path) return
    const lp = ledgerPath(path)
    if (!lp) return
    let text: string
    try {
      text = await $.fs.read(lp)
    } catch {
      return // sin ledger todavía
    }
    // el plan activo cambió durante la lectura: este ledger ya no es el vigente
    if ((await read($, planPath)) !== path || JSON.stringify(await read($, plan)) !== JSON.stringify(current)) return
    const stored = await read($, doneStored)
    const fresh = completedFromLedger(text).filter(n => current.tasks.some(t => t.n === n) && !stored.includes(n))
    await markDone($, current, path, fresh)
  } catch {
    // nunca romper la sesión
  }
}

// Persiste solo las tasks que acaban de pasar a hecha, contra el plan activo en ese momento.
async function persistCompleted($: Eng, done: SessionTask[]): Promise<void> {
  try {
    const current = await read($, plan)
    const path = await read($, planPath)
    if (!current || !path || done.length === 0) return
    const stored = await read($, doneStored)
    const fresh: number[] = []
    for (const t of done) {
      if (t.planPath != null && t.planPath !== path) continue
      const n = matchTask(t.subject, current)
      if (n !== undefined && !stored.includes(n) && !fresh.includes(n)) fresh.push(n)
    }
    await markDone($, current, path, fresh)
  } catch {
    // nunca romper la sesión
  }
}

const nowMs = ($: Eng): Promise<number> => $.clock.now().catch(() => Date.now())

// Avanza la fase (solo hacia delante). Un cambio dentro de un ciclo abierto deja un hito.
async function advancePhase($: Eng, to: PhaseId, refresh = true, reopen = false): Promise<void> {
  const prev = await read($, phase)
  const next = advance(prev, to, reopen)
  if (next === prev) return
  await update($, phase, () => next)
  const reopened =
    prev.current !== null && next.current !== null && PHASES.indexOf(next.current) < PHASES.indexOf(prev.current)
  if (prev.closedAt !== null || reopened) {
    // ciclo nuevo: sin hito ni destello heredados, y un spec o plan nuevo suelta el plan anterior
    await update($, milestone, () => null)
    await update($, flash, () => null)
    if (to === 'spec' || to === 'plan') await dropPlan($)
  } else if (prev.current !== null) {
    const step: Milestone = { from: prev.current, to, at: await nowMs($) }
    await update($, milestone, () => step)
  }
  ensureTicker($)
  if (refresh) await refreshRepo($)
}

// Leer o escribir un spec abre el ciclo (o refresca su título); en plan o después no reinicia nada.
async function onSpec($: Eng, abs: string, wrote: boolean): Promise<void> {
  const prev = await read($, phase)
  // escribir otro spec con la implementación ya en marcha abre un ciclo nuevo; leerlo, no
  const another = wrote && abs !== prev.source && prev.current !== null && PHASES.indexOf(prev.current) >= PHASES.indexOf('impl')
  const closed = prev.closedAt !== null || another
  const early = prev.current === null || prev.current === 'spec' || closed
  if (!early) return
  let title: string | null = null
  try {
    title = specTitleFrom(await $.fs.read(abs))
  } catch {
    // sin título
  }
  if (closed || abs !== prev.source) {
    await update($, phase, (): PhaseState => ({ ...EMPTY_PHASE, current: 'spec', source: abs, specTitle: title }))
    await update($, milestone, () => null)
    await update($, flash, () => null)
    if (closed && prev.current !== 'spec') await dropPlan($)
    await refreshRepo($)
    return
  }
  await update($, phase, p => ({ ...p, specTitle: title ?? p.specTitle }))
  await advancePhase($, 'spec')
}

// Suelta el plan del ciclo anterior (salvo fijado): la franja no sigue enseñando sus Tasks ya terminadas.
async function dropPlan($: Eng): Promise<void> {
  if (await read($, pinned)) return
  await update($, planPath, () => null)
  await update($, plan, () => null)
  await update($, planError, () => null)
  await update($, doneStored, () => [])
}

// Un plan leído o escrito por la sesión principal: lo carga y, si es otro que el activo, reinicia la fase a «plan».
async function onPlan($: Eng, abs: string): Promise<void> {
  // fijado: solo se relee el plan fijado; otros planes se ignoran
  if ((await read($, pinned)) && abs !== (await read($, planPath))) return
  const old = await read($, planPath)
  if (old !== null && abs !== old) {
    const prev = await read($, phase)
    await update($, phase, (): PhaseState => ({ ...EMPTY_PHASE, current: 'plan', source: abs, specTitle: prev.specTitle }))
    await update($, milestone, () => null)
    await update($, flash, () => null)
  }
  await loadPlan($, abs)
  await advancePhase($, 'plan', false) // loadPlan ya refrescó el repo
}

// Un Bash que nombra un plan (o la carpeta de su ledger SDD) lo carga como si se hubiera leído. La ruta relativa
// se prueba contra el `cd` inicial, la raíz del plan y del spec activos y el cwd de la sesión; solo cuenta si se lee.
async function planFromBash($: Eng, cmd: string): Promise<void> {
  if (await read($, pinned)) return
  const refs = planRefsInCommand(cmd)
  if (refs.length === 0) return
  const cwd = await $.session.cwd()
  const cd = cdTarget(cmd)
  const bases = [cd === null ? null : absolutePath(cwd, cd), repoRoot(await read($, planPath)), repoRoot((await read($, phase)).source), cwd]
  const current = await read($, planPath)
  for (const ref of refs) {
    const candidates = ref.startsWith('/') ? [ref] : bases.filter((b): b is string => b !== null).map(b => absolutePath(b, ref))
    for (const abs of [...new Set(candidates)]) {
      if (abs === current) return
      let parsed: Plan | undefined
      try {
        parsed = parsePlan(await $.fs.read(abs))
      } catch {
        parsed = undefined
      }
      if (parsed) {
        await onPlan($, abs)
        return
      }
    }
  }
}

const PANE = 'roadmap'
const LIVE = ['pending', 'running', 'waiting']
const TICK_MS = 250
const BAND_KEY = 'bandHidden'

// Un solo reloj de franja por carga del mod: se cancela al quedarse sin agentes, hito ni destello
// y se rearma al llegar el siguiente, así no se apila ni escribe en vacío.
let ticker: { cancel: () => void } | undefined
let poller: { cancel: () => void } | undefined

function ensureTicker($: Eng): void {
  if (ticker) return
  let wasAlive = false
  try {
    ticker = $.clock.every(TICK_MS, async () => {
      try {
        const alive = async (): Promise<boolean> => {
          const t = await nowMs($)
          const m = await read($, milestone)
          const f = await read($, flash)
          const ph = await read($, phase)
          return (
            (await read($, agents)).length > 0 ||
            (m !== null && t - m.at < MILESTONE_MS) ||
            (f !== null && t - f.at < FLASH_MS) ||
            (ph.closedAt !== null && t - ph.closedAt < CLOSED_SHOW_MS)
          )
        }
        if (!(await alive())) {
          // último repintado: destello, hito o franja de cierre no se quedan congelados
          if (wasAlive) await update($, tick, n => n + 1)
          wasAlive = false
          if (!(await alive())) {
            ticker?.cancel()
            ticker = undefined
          }
          return
        }
        wasAlive = true
        await update($, tick, n => n + 1)
      } catch {
        // el reloj es solo decorado
      }
    })
  } catch {
    ticker = undefined
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const ran = await next(e)
    try {
      await $.command.register({
        name: 'roadmap',
        description:
          'Roadmap del plan: abre/cierra el panel, oculta/muestra la franja (/roadmap franja), fija un plan (/roadmap <ruta>), borra su progreso (/roadmap reset) o termina el ciclo de fases (/roadmap fin)',
      })
    } catch {
      // sin comando, el resto sigue
    }
    try {
      // limpia una entrada de estado heredada de una carga anterior; el mod ya no dibuja barra de estado
      $.ui.status(undefined)
    } catch {
      // sin barra de estado que limpiar
    }
    try {
      await update($, bandHidden, () => false)
      if ((await $.store.get(BAND_KEY)) === true) await update($, bandHidden, () => true)
    } catch {
      // sin almacén, la franja queda visible
    }
    try {
      poller?.cancel()
      poller = $.clock.every(5000, async () => {
        try {
          const cur = (await read($, phase)).current
          if (cur === 'impl' || cur === 'review') await syncLedger($)
          const bg = (await read($, agents)).filter(a => a.background)
          if (bg.length === 0) return
          const live = (await $.agent.list()).filter(a => LIVE.includes(a.status))
          await update($, agents, l => keepLiveAgents(l, live))
        } catch {
          // sondeo best effort
        }
      })
    } catch {
      // sin sondeo
    }
    ensureTicker($)
    return ran
  })

  on('agent.spawn', async ($, e, next) => {
    const ran = await next(e)
    try {
      if (ran.deny === undefined) {
        const row: ActiveAgent = {
          id: e.tool_use_id,
          description: e.description,
          model: e.model ?? e.parentModel,
          background: e.background,
          agentId: ran.agentId,
          startedAt: await $.clock.now().catch(() => Date.now()),
          taskN: agentTask(e.description, (await read($, plan)) ?? undefined),
        }
        await update($, agents, l => [...l.filter(x => !(x.id === row.id && x.description === row.description)), row])
        if (row.taskN !== undefined) {
          await advancePhase($, 'impl')
        }
        ensureTicker($)
      }
    } catch {
      // observar nunca bloquea
    }
    return ran
  })

  on('tool.call', { tool: 'Agent' }, async ($, e, next) => {
    const ran = await next(e)
    try {
      await update($, agents, l => l.filter(x => x.id !== e.tool_use_id || x.background))
    } catch {
      // observar nunca bloquea
    }
    return ran
  })

  on('command.run', { command: 'roadmap' }, async ($, e) => {
    try {
      const arg = e.args.trim()
      if (arg === 'reset') {
        await update($, phase, () => EMPTY_PHASE)
        await update($, milestone, () => null)
        await update($, flash, () => null)
        const path = await read($, planPath)
        if (!path) return { text: 'No hay plan activo.' }
        await $.store.delete(storeKey(path))
        await update($, doneStored, () => [])
        return { text: 'Progreso guardado borrado para este plan.' }
      }
      if (arg === 'fin') {
        // termina el ciclo de fases sin tocar el progreso guardado del plan
        await update($, phase, () => EMPTY_PHASE)
        await update($, milestone, () => null)
        await update($, flash, () => null)
        return { text: 'Ciclo de fases terminado.' }
      }
      if (arg === 'franja') {
        const hidden = !(await read($, bandHidden))
        await update($, bandHidden, () => hidden)
        try {
          await $.store.set(BAND_KEY, hidden)
        } catch {
          // sin persistencia: vale para esta sesión
        }
        return { text: hidden ? 'Franja oculta.' : 'Franja visible.' }
      }
      if (arg) {
        await update($, pinned, () => true)
        await loadPlan($, arg)
        await advancePhase($, 'impl', false)
        await $.ui.open({ id: PANE, title: 'Roadmap' })
        await update($, isOpen, () => true)
        const abs = absolutePath(await $.session.cwd(), arg)
        return { text: (await read($, planError)) ? `Plan no legible: ${abs}` : `Plan fijado: ${abs}` }
      }
      if (await read($, isOpen)) {
        await $.ui.close({ id: PANE })
        await update($, isOpen, () => false)
        return { text: 'Panel de roadmap cerrado.' }
      }
      await $.ui.open({ id: PANE, title: 'Roadmap' })
      await update($, isOpen, () => true)
      return { text: 'Panel de roadmap abierto.' }
    } catch {
      return { text: 'No se pudo ejecutar /roadmap.' }
    }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    try {
      if (e.props.hasSurvey || (await read($, bandHidden))) return next(e)
      const current = (await read($, plan)) ?? undefined
      const all = [...(await read($, tasks)), ...(await read($, todos))]
      const r = buildRoadmapFor(current, all, await read($, doneStored), await read($, planPath))
      const live = (await read($, agents)).map(a => ({ ...a, taskN: a.taskN ?? agentTask(a.description, current) }))
      const now = await nowMs($)
      const ph = await read($, phase)
      // fijada, o con fase en curso (hasta 5 s tras cerrarla), o con alguna task de la sesión viva
      const showBand =
        (await read($, pinned)) ||
        (ph.current !== null && !(ph.closedAt !== null && now - ph.closedAt > CLOSED_SHOW_MS)) ||
        all.some(t => t.status !== 'completed')
      if (!showBand) return next(e)
      const columns = e.props.bodyColumns || e.viewport?.columns || 80
      const rows = metroBand({
        title: current?.title,
        repo: await read($, repo),
        roadmap: r,
        agents: live,
        width: Math.max(1, columns - 4), // borde (2) + relleno (2)
        maxRows: e.props.maxRows - 2, // el borde se lleva dos filas
        tick: await read($, tick),
        now,
        phase: ph,
        milestone: await read($, milestone),
        flash: await read($, flash),
        looseTasks: all,
      })
      if (rows.length === 0) return next(e)
      const { Box, Text } = $.ui.resolve(e)
      return (
        <Box borderStyle="round" borderColor={PALETTE.border} flexDirection="column" paddingX={1} width={columns}>
          {rows.map(row => (
            <Text wrap="truncate">
              {row.map(s => (
                <Text color={s.color} bold={s.bold} dimColor={s.dim}>
                  {s.text}
                </Text>
              ))}
            </Text>
          ))}
        </Box>
      )
    } catch {
      return next(e)
    }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text } = $.ui.resolve(e)
    const current = await read($, plan)
    const error = await read($, planError)
    const all = [...(await read($, tasks)), ...(await read($, todos))]
    const r = buildRoadmapFor(current ?? undefined, all, await read($, doneStored), await read($, planPath))
    const looseLive = r.loose.filter(t => t.status !== 'completed')
    const hiddenDone = r.loose.length - looseLive.length
    const running = await read($, agents)
    const reserved = 6 + looseLive.length + (hiddenDone > 0 ? 1 : 0) + running.length
    const room = Math.max(3, (e.viewport?.rows ?? 30) - reserved)
    const win = visibleRows(r.rows, room)
    const mark = { done: '✔', active: '▶', pending: '○' } as const

    return (
      <Box flexDirection="column">
        {current ? (
          <Box flexDirection="column">
            <Text bold>plan: {current.title}</Text>
            <Text>
              {progressBar(r.done, r.total)} {r.done}/{r.total}
            </Text>
            {win.hiddenBefore > 0 && <Text dimColor>… {win.hiddenBefore} más</Text>}
            {win.rows.map(row => (
              <Text dimColor={row.state === 'done'} bold={row.state === 'active'}>
                {mark[row.state]} {row.n} {row.title}
              </Text>
            ))}
            {win.hiddenAfter > 0 && <Text dimColor>… {win.hiddenAfter} más</Text>}
          </Box>
        ) : (
          <Text dimColor>{error ?? 'Sin plan detectado'}</Text>
        )}
        {r.loose.length > 0 && <Text dimColor>─ Tasks sesión ─</Text>}
        {looseLive.map(t => (
          <Text bold={t.status === 'in_progress'}>
            {t.status === 'in_progress' ? '▶' : '○'} {t.subject}
          </Text>
        ))}
        {hiddenDone > 0 && <Text dimColor>✔ {hiddenDone} completadas</Text>}
        {running.length > 0 && <Text dimColor>─ Subagentes ─</Text>}
        {running.map(a => (
          <Text>
            ⚙ {a.description} · {a.model}
          </Text>
        ))}
      </Box>
    )
  })

  on('tool.call', { tool: 'TaskCreate' }, async ($, e, next) => {
    const ran = await next(e)
    try {
      const task = (ran.result as { task?: { id?: string; subject?: string } } | undefined)?.task
      if (!e.agentId && ran.deny === undefined && !ran.isError && task?.id) {
        const stamp = await read($, planPath)
        const row: SessionTask = { id: task.id, subject: task.subject ?? e.subject, status: 'pending', planPath: stamp }
        await update($, tasks, l => [...l.filter(x => x.id !== row.id), row])
      }
    } catch {
      // observar nunca bloquea
    }
    return ran
  })

  on('tool.call', { tool: 'TaskUpdate' }, async ($, e, next) => {
    const ran = await next(e)
    try {
      if (!e.agentId && ran.deny === undefined && !ran.isError) {
        const prev = await read($, tasks)
        const stamp = await read($, planPath)
        let next2: SessionTask[]
        if (e.status === 'deleted') {
          next2 = prev.filter(x => x.id !== e.taskId)
        } else if (!prev.some(x => x.id === e.taskId)) {
          next2 = e.subject
            ? [...prev, { id: e.taskId, subject: e.subject, status: (e.status ?? 'pending') as TaskStatus, planPath: stamp }]
            : prev
        } else {
          next2 = prev.map(x =>
            x.id === e.taskId
              ? {
                  ...x,
                  subject: e.subject ?? x.subject,
                  status: (e.status ?? x.status) as TaskStatus,
                  planPath: x.planPath ?? (e.status === 'completed' ? stamp : x.planPath),
                }
              : x,
          )
        }
        await update($, tasks, () => next2)
        await persistCompleted($, newlyCompleted(prev, next2))
      }
    } catch {
      // observar nunca bloquea
    }
    return ran
  })

  on('tool.call', { tool: 'TodoWrite' }, async ($, e, next) => {
    const ran = await next(e)
    try {
      if (!e.agentId && ran.deny === undefined && !ran.isError) {
        const prev = await read($, todos)
        const stamp = await read($, planPath)
        const fresh = stampTodos(
          prev,
          e.todos.map((t, i): SessionTask => ({ id: `todo:${i}`, subject: t.content, status: t.status })),
          stamp,
        )
        await update($, todos, () => fresh)
        await persistCompleted($, todosNewlyCompleted(prev, fresh))
      }
    } catch {
      // observar nunca bloquea
    }
    return ran
  })

  on('tool.call', { tool: ['Read', 'Write', 'Edit'] }, async ($, e, next) => {
    const ran = await next(e)
    try {
      if (!e.agentId && ran.deny === undefined && !ran.isError && isLedgerFile(e.file_path)) {
        await syncLedger($)
      } else if (!e.agentId && ran.deny === undefined && !ran.isError && PLAN_RE.test(e.file_path)) {
        await onPlan($, absolutePath(await $.session.cwd(), e.file_path))
      } else if (!e.agentId && ran.deny === undefined && !ran.isError && SPEC_RE.test(e.file_path)) {
        await onSpec($, absolutePath(await $.session.cwd(), e.file_path), e.tool !== 'Read')
      }
    } catch {
      // observar nunca bloquea
    }
    return ran
  })

  on('tool.call', { tool: 'Skill' }, async ($, e, next) => {
    const ran = await next(e)
    try {
      if (!e.agentId && ran.deny === undefined && !ran.isError) {
        const to = phaseForSkill(e.skill)
        if (to) await advancePhase($, to, true, true)
      }
    } catch {
      // observar nunca bloquea
    }
    return ran
  })

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const ran = await next(e)
    try {
      if (!e.agentId && ran.deny === undefined && !ran.isError) await planFromBash($, e.command)
      if (!e.agentId && ran.deny === undefined && !ran.isError && touchesLedgerCommand(e.command)) await syncLedger($)
      if (!e.agentId && ran.deny === undefined && !ran.isError && isCloseCommand(e.command)) {
        const prev = await read($, phase)
        if ((prev.current === 'close' || prev.current === 'review') && prev.closedAt === null) {
          const at = await nowMs($)
          await update($, phase, p => ({ ...p, closedAt: at }))
          await update($, milestone, () => ({ from: prev.current, to: 'done', at }))
          ensureTicker($)
        }
      }
    } catch {
      // observar nunca bloquea
    }
    return ran
  })
}

