import type { Plan, PlanTask } from '../../types'

const TITLE_RE = /^#\s+(.+?)\s*$/
const TASK_RE = /^#{2,4}\s+Task\s+(\d+)\s*:\s*(.+?)\s*$/i
const HEADING_RE = /^#{1,4}\s/
const STEP_RE = /^\s*-\s+\[( |x|X)\]/
const FENCE_RE = /^\s*(```|~~~)/

function cleanTitle(raw: string): string {
  return raw
    .replace(/\s+[—–-]\s+Plan de implementaci[oó]n$/i, '')
    .replace(/\s+Implementation Plan$/i, '')
    .replace(/\s+[—–-]\s+plan$/i, '')
    .trim()
}

export function parsePlan(text: string): Plan | undefined {
  let title = ''
  let inFence = false
  let current: PlanTask | undefined
  const tasks: PlanTask[] = []

  for (const line of text.split(/\r?\n/)) {
    if (FENCE_RE.test(line)) {
      inFence = !inFence
      continue
    }
    if (inFence) continue

    const task = TASK_RE.exec(line)
    if (task) {
      current = { n: Number(task[1]), title: task[2] ?? '', steps: 0, stepsDone: 0 }
      tasks.push(current)
      continue
    }
    if (!title) {
      const t = TITLE_RE.exec(line)
      if (t) {
        title = cleanTitle(t[1] ?? '')
        continue
      }
    }
    if (HEADING_RE.test(line)) {
      current = undefined
      continue
    }
    const step = STEP_RE.exec(line)
    if (step && current) {
      current.steps++
      if (step[1] !== ' ') current.stepsDone++
    }
  }

  return tasks.length > 0 ? { title: title || 'Plan', tasks } : undefined
}

export function isTaskDoneInFile(t: PlanTask): boolean {
  return t.steps > 0 && t.stepsDone === t.steps
}

