import type { ActiveAgent, Plan, SessionTask } from '../../types'
import { isTaskDoneInFile } from './planParser'

export type RowState = 'done' | 'active' | 'pending'
export type RoadmapRow = { n: number; title: string; state: RowState }
export type Roadmap = {
  rows: RoadmapRow[]
  done: number
  total: number
  loose: SessionTask[]
  completedByTasks: number[]
}

const MIN_TITLE_MATCH = 8

export function normalize(s: string): string {
  return s
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
}

export function matchTask(subject: string, plan: Plan): number | undefined {
  const byNumber = /\btask\s+(\d+)\b/i.exec(subject)
  if (byNumber) {
    const n = Number(byNumber[1])
    if (plan.tasks.some(x => x.n === n)) return n
  }
  const s = normalize(subject)
  for (const task of plan.tasks) {
    const title = normalize(task.title)
    const shorter = s.length < title.length ? s : title
    if (shorter.length < MIN_TITLE_MATCH) continue
    if (s.includes(title) || title.includes(s)) return task.n
  }
  return undefined
}

export function buildRoadmap(plan: Plan | undefined, tasks: SessionTask[], stored: number[]): Roadmap {
  if (!plan) return { rows: [], done: 0, total: 0, loose: [...tasks], completedByTasks: [] }

  const matched = new Map<number, SessionTask[]>()
  const loose: SessionTask[] = []
  for (const task of tasks) {
    const n = matchTask(task.subject, plan)
    if (n === undefined) loose.push(task)
    else matched.set(n, [...(matched.get(n) ?? []), task])
  }

  const completedByTasks: number[] = []
  const rows = plan.tasks.map((pt): RoadmapRow => {
    const mine = matched.get(pt.n) ?? []
    const byTasks = mine.some(x => x.status === 'completed')
    if (byTasks) completedByTasks.push(pt.n)
    const isDone = byTasks || stored.includes(pt.n) || isTaskDoneInFile(pt)
    const isActive = !isDone && mine.some(x => x.status === 'in_progress')
    return { n: pt.n, title: pt.title, state: isDone ? 'done' : isActive ? 'active' : 'pending' }
  })

  return {
    rows,
    done: rows.filter(r => r.state === 'done').length,
    total: rows.length,
    loose,
    completedByTasks,
  }
}

/** Tasks que cuentan para el plan activo: las de ese plan y las creadas sin plan. */
export function belongsToPlan(task: SessionTask, planPath: string | null): boolean {
  return task.planPath == null || task.planPath === planPath
}

/** Como buildRoadmap, pero las tasks de otro plan no puntúan: pasan a sueltas. */
export function buildRoadmapFor(
  plan: Plan | undefined,
  tasks: SessionTask[],
  stored: number[],
  planPath: string | null,
): Roadmap {
  const mine = tasks.filter(t => belongsToPlan(t, planPath))
  const foreign = tasks.filter(t => !belongsToPlan(t, planPath))
  const r = buildRoadmap(plan, mine, stored)
  return { ...r, loose: [...r.loose, ...foreign] }
}

/** Tasks que han pasado a `completed` entre dos listas (por id). */
export function newlyCompleted(prev: SessionTask[], next: SessionTask[]): SessionTask[] {
  return next.filter(t => t.status === 'completed' && prev.find(p => p.id === t.id)?.status !== 'completed')
}

/** Todos nuevos: heredan el sello de plan del todo previo con el mismo texto, o el plan activo. */
export function stampTodos(prev: SessionTask[], next: SessionTask[], planPath: string | null): SessionTask[] {
  return next.map(t => {
    const before = prev.find(p => p.subject === t.subject)
    return { ...t, planPath: before ? before.planPath : planPath }
  })
}

/** Quita los todos que ya estaban completados antes (mismo texto): no son transición. */
export function todosNewlyCompleted(prev: SessionTask[], next: SessionTask[]): SessionTask[] {
  return next.filter(
    t => t.status === 'completed' && !prev.some(p => p.subject === t.subject && p.status === 'completed'),
  )
}

/** Agentes en segundo plano que siguen vivos: por agentId, o por descripción si no hay id. */
export function keepLiveAgents(
  agents: ActiveAgent[],
  live: { id: string; description: string }[],
): ActiveAgent[] {
  return agents.filter(
    a =>
      !a.background ||
      (a.agentId ? live.some(x => x.id === a.agentId) : live.some(x => x.description === a.description)),
  )
}

