import type { ActiveAgent, Milestone, Plan, PhaseState, SessionTask, TaskFlash } from '../../types'
import { milestoneStage } from './clawd'
import { PALETTE } from './palette'
import { PHASE_LABEL, phaseRow } from './phases'
import type { Roadmap, RoadmapRow } from './taskMatcher'
import { cellWidth, fitRow, pulseOn, rowWidth, truncate } from './text'
import type { BandRow, Seg } from './text'

// Lógica pura de la franja «línea de metro»: sin `$`, sin átomos, sin estado.

export { cellWidth, pulseOn } from './text'
export type { BandRow, Seg } from './text'

export type BandAgent = Pick<ActiveAgent, 'id' | 'description' | 'model'> & {
  startedAt?: number
  taskN?: number
}

export type RepoInfo = { worktree: string; branch: string }

export type MetroInput = {
  /** Título del plan activo (cabecera). */
  title?: string
  /** Worktree y rama del plan activo; si falta (o es null) la cabecera muestra el título. */
  repo?: RepoInfo | null
  roadmap: Roadmap
  agents: BandAgent[]
  /** Columnas útiles dentro de la caja (ya sin borde ni relleno). */
  width: number
  /** Filas útiles dentro de la caja (ya sin el borde). */
  maxRows: number
  tick: number
  now: number
  /** Fase del desarrollo; con `current` la primera fila es la de fases. */
  phase?: PhaseState
  /** Hito en curso (la chispa camina y celebra). */
  milestone?: Milestone | null
  /** Destello de la estación de la Task recién completada. */
  flash?: TaskFlash | null
  /** Tasks de la sesión, para el modo «solo tasks» (sin plan ni fase). */
  looseTasks?: SessionTask[]
}

const SPINNER = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏']
const MAX_TREE = 3
const DONE = PALETTE.done
const CURRENT = PALETTE.currentStrong
const CURRENT_WEAK = PALETTE.currentWeak
const PENDING = PALETTE.pending
const ACCENT = PALETTE.accent
const FLOW = PALETTE.flow
const SOFT = PALETTE.soft
const FLOW_LEN = 3
export const FLASH_MS = 800
export const CLOSED_SHOW_MS = 5000

export function elapsed(ms: number): string {
  const total = Math.max(0, Math.floor(ms / 1000))
  const m = Math.floor(total / 60)
  const s = total % 60
  return `${m}m ${String(s).padStart(2, '0')}s`
}

export function modelName(model: string): string {
  const lower = model.toLowerCase()
  for (const k of ['opus', 'sonnet', 'haiku']) if (lower.includes(k)) return k
  return model
}

/** Task del plan que menciona la descripción de un agente («… Task 8 …»). */
export function agentTask(description: string, plan: Plan | undefined): number | undefined {
  const m = /\btask\s+(\d+)\b/i.exec(description)
  if (!m || !plan) return undefined
  const n = Number(m[1])
  return plan.tasks.some(t => t.n === n) ? n : undefined
}

// ---------- línea de metro ----------

type Place = { idx: number; pos: number; label: string }

const overlaps = (a: { pos: number; len: number }, b: { pos: number; len: number }) =>
  !(a.pos + a.len + 1 <= b.pos || b.pos + b.len + 1 <= a.pos)

/** Columna de cada estación al repartir `width` entre `n` (resto a los primeros huecos). */
export function stationColumns(n: number, width: number): number[] {
  if (n <= 1) return [0]
  const spare = Math.max(0, width - n)
  const base = Math.floor(spare / (n - 1))
  const extra = spare % (n - 1)
  const cols = [0]
  for (let i = 1; i < n; i++) cols.push(cols[i - 1]! + 1 + base + (i - 1 < extra ? 1 : 0))
  return cols
}

/** Etiquetas numéricas bajo su estación: todas si caben; si no, primero, último, actual y múltiplos de 5. */
function placeLabels(items: RoadmapRow[], cols: number[], width: number, current: number): Place[] {
  const all = items.map((r, idx) => {
    const label = String(r.n)
    return { idx, pos: Math.max(0, Math.min(cols[idx]!, width - label.length)), label }
  })
  const clash = all.some((p, i) => i > 0 && overlaps({ pos: p.pos, len: p.label.length }, { pos: all[i - 1]!.pos, len: all[i - 1]!.label.length }))
  if (!clash) return all
  const order: number[] = []
  const add = (i: number) => {
    if (i >= 0 && i < items.length && !order.includes(i)) order.push(i)
  }
  add(current)
  add(0)
  add(items.length - 1)
  items.forEach((r, i) => r.n % 5 === 0 && add(i))
  const placed: Place[] = []
  for (const i of order) {
    const p = all[i]!
    if (!placed.some(q => overlaps({ pos: p.pos, len: p.label.length }, { pos: q.pos, len: q.label.length }))) placed.push(p)
  }
  return placed.sort((a, b) => a.pos - b.pos)
}

/** Desplazamiento del brillo que «fluye» por el tramo pendiente: función pura del tick. */
export function flowOffset(tick: number, len: number): number {
  return len > 0 ? ((Math.floor(tick) % len) + len) % len : 0
}

type Anim = { tick: number; live: boolean; flashN?: number }

function stationRow(items: RoadmapRow[], cols: number[], anim: Anim): BandRow {
  const out: BandRow = []
  const current = items.findIndex(r => r.state === 'active')
  // el tramo pendiente tras la actual: un único «carril» por el que corre el brillo
  let strip = 0
  if (anim.live && current >= 0) for (let i = current; i < items.length - 1; i++) strip += cols[i + 1]! - cols[i]! - 1
  const offset = flowOffset(anim.tick, strip)
  let g = 0
  items.forEach((r, i) => {
    if (anim.flashN === r.n) out.push({ text: '●', color: PALETTE.flash, bold: true })
    else if (r.state === 'done') out.push({ text: '●', color: DONE })
    else if (r.state === 'active') {
      if (anim.live && !pulseOn(anim.tick)) out.push({ text: '●', color: CURRENT_WEAK })
      else out.push({ text: '◉', color: CURRENT, bold: true })
    } else out.push({ text: '○', color: PENDING })
    if (i < items.length - 1) {
      const len = cols[i + 1]! - cols[i]! - 1
      if (r.state === 'done') {
        out.push({ text: '━'.repeat(len), color: DONE })
      } else if (strip > 0 && i >= current) {
        let run = ''
        let bright = false
        for (let c = 0; c < len; c++, g++) {
          const hot = (((g - offset) % strip) + strip) % strip < FLOW_LEN
          if (c > 0 && hot !== bright) {
            out.push(bright ? { text: run, color: FLOW, bold: true } : { text: run, color: PENDING })
            run = ''
          }
          bright = hot
          run += '┄'
        }
        out.push(bright ? { text: run, color: FLOW, bold: true } : { text: run, color: PENDING })
      } else {
        out.push({ text: '┄'.repeat(len), color: PENDING })
      }
    }
  })
  return out
}

function numberRow(items: RoadmapRow[], cols: number[], width: number, current: number, offset: number): BandRow {
  const out: BandRow = []
  if (offset > 0) out.push({ text: ' '.repeat(offset) })
  let col = 0
  for (const p of placeLabels(items, cols, width, current)) {
    if (p.pos > col) out.push({ text: ' '.repeat(p.pos - col) })
    const isCurrent = p.idx === current
    out.push(isCurrent ? { text: p.label, color: CURRENT, bold: true } : { text: p.label, dim: true })
    col = p.pos + p.label.length
  }
  return out
}

const MIN_STEP = 3 // estación + conector de al menos 2 columnas

function track(rows: RoadmapRow[], width: number, anim: Anim): { line: BandRow; numbers: BandRow } {
  const n = rows.length
  const current = rows.findIndex(r => r.state === 'active')
  if ((n - 1) * MIN_STEP + 1 <= width) {
    const cols = stationColumns(n, width)
    return { line: stationRow(rows, cols, anim), numbers: numberRow(rows, cols, width, current, 0) }
  }
  // ventana alrededor de la actual (o de la primera pendiente) con ‹N y N›, a todo el ancho
  let focus = current
  if (focus < 0) focus = rows.findIndex(r => r.state === 'pending')
  if (focus < 0) focus = n - 1
  for (let k = n - 1; k >= 1; k--) {
    const start = Math.max(0, Math.min(focus - Math.floor((k - 1) / 2), n - k))
    const ha = n - start - k
    const left = start > 0 ? `‹${start} ` : ''
    const right = ha > 0 ? ` ${ha}›` : ''
    const inner = width - left.length - right.length
    if ((k - 1) * MIN_STEP + 1 <= inner || k === 1) {
      const visible = rows.slice(start, start + k)
      const cols = stationColumns(k, Math.max(1, inner))
      const line: BandRow = []
      if (left) line.push({ text: left, dim: true })
      line.push(...stationRow(visible, cols, anim))
      if (right) line.push({ text: right, dim: true })
      return { line, numbers: numberRow(visible, cols, Math.max(1, inner), focus - start, left.length) }
    }
  }
  const cols = stationColumns(n, width)
  return { line: stationRow(rows, cols, anim), numbers: numberRow(rows, cols, width, current, 0) }
}

// ---------- franja ----------

const isReview = (d: string) => /^\s*(review|revis)/i.test(d)

function agentRow(prefix: string, a: BandAgent, now: number, width: number, tick: number): BandRow {
  const icon = isReview(a.description) ? '🔍' : '⚙'
  const spin = SPINNER[Math.abs(tick) % SPINNER.length]!
  const model = modelName(a.model)
  const time = elapsed(now - (a.startedAt ?? now))
  const fixed = cellWidth(prefix) + 1 + 1 + cellWidth(icon) + 1 + cellWidth(` · ${model} · ${time}`)
  const desc = truncate(a.description, Math.max(1, width - fixed))
  return [
    { text: prefix, dim: true },
    { text: spin, color: CURRENT },
    { text: ` ${icon} ${desc}` },
    { text: ' · ', dim: true },
    { text: model, color: SOFT },
    { text: ` · ${time}`, dim: true },
  ]
}

function pctColor(pct: number): string {
  return pct >= 100 ? DONE : pct >= 34 ? CURRENT : PENDING
}

const BAR_CELLS = 8

/** Barra de 8 celdas y «hechas/total · %» (parte derecha de la cabecera). */
function progressRight(done: number, total: number): BandRow {
  const pct = total > 0 ? Math.round((done / total) * 100) : 0
  const filled = total > 0 ? Math.round((done / total) * BAR_CELLS) : 0
  return [
    { text: '█'.repeat(filled), color: DONE },
    { text: '░'.repeat(BAR_CELLS - filled), dim: true },
    { text: ` ${done}/${total} · `, dim: true },
    { text: `${pct}%`, color: pctColor(pct), bold: true },
  ]
}

/** Nombre de la cabecera: con `live`, una ventana de 3 letras en `soft` lo recorre (función pura del tick). */
function nameSegs(text: string, tick: number, live: boolean): Seg[] {
  if (!live) return [{ text, color: ACCENT, bold: true }]
  const chars = [...text]
  const p = Math.abs(Math.floor(tick)) % (chars.length + 8)
  return [
    { text: chars.slice(0, p).join(''), color: ACCENT, bold: true },
    { text: chars.slice(p, p + 3).join(''), color: SOFT, bold: true },
    { text: chars.slice(p + 3).join(''), color: ACCENT, bold: true },
  ].filter(sg => sg.text)
}

type HeaderOpts = {
  title: string
  repo: RepoInfo | null | undefined
  right: BandRow
  complete: boolean
  width: number
  tick: number
  live: boolean
}

function header({ title, repo, right, complete, width, tick, live }: HeaderOpts): BandRow {
  const rw = rowWidth(right)
  const badge = complete ? ' ✓ completado' : ''
  const room = Math.max(1, width - rw - 3)
  let leftSegs: BandRow
  if (repo) {
    // «◆ worktree  ⎇ rama»: se recorta primero la rama y luego el worktree
    const avail = Math.max(2, room - cellWidth('◆ ') - cellWidth('  ⎇ '))
    const branch = truncate(repo.branch, Math.max(1, avail - cellWidth(repo.worktree)))
    const worktree = truncate(repo.worktree, Math.max(1, avail - cellWidth(branch)))
    leftSegs = [
      { text: '◆ ', color: ACCENT },
      ...nameSegs(worktree, tick, live),
      { text: '  ⎇ ', color: SOFT },
      { text: branch, color: SOFT },
    ]
    const showBadge = complete && rowWidth(leftSegs) + cellWidth(badge) <= room
    if (showBadge) leftSegs.push({ text: badge, color: DONE, bold: true })
    const tail = `  ${title}`
    if (title && rowWidth(leftSegs) + cellWidth(tail) <= room) leftSegs.push({ text: tail, dim: true })
  } else {
    const showBadge = complete && cellWidth(title) + cellWidth(badge) <= room
    const left = truncate(title, showBadge ? room - cellWidth(badge) : room)
    leftSegs = [
      { text: '◆ ', color: ACCENT },
      ...nameSegs(left, tick, live),
      ...(showBadge ? [{ text: badge, color: DONE, bold: true }] : []),
    ]
  }
  const pad = Math.max(1, width - rowWidth(leftSegs) - rw)
  return [...leftSegs, { text: ' '.repeat(pad) }, ...right]
}

function looseRow(t: SessionTask, doing: boolean, spin: string, width: number): BandRow {
  const subject = truncate(t.subject, Math.max(1, width - 2))
  return doing ? [{ text: `${spin} `, color: CURRENT, bold: true }, { text: subject, bold: true }] : [{ text: '○ ', color: PENDING }, { text: subject }]
}

type CoreKind = 'phases' | 'header' | 'line' | 'numbers' | 'active'

export function metroBand(input: MetroInput): BandRow[] {
  const { roadmap, agents, width, maxRows, tick, now, phase, milestone, flash, looseTasks } = input
  if (maxRows <= 0 || width <= 0) return []
  const hasPlan = roadmap.rows.length > 0
  const current = phase?.current ?? null
  const phaseMode = !hasPlan && current !== null
  const pendingTasks = (looseTasks ?? []).filter(t => t.status !== 'completed')
  const tasksMode = !hasPlan && current === null && pendingTasks.length > 0
  const looseActive = roadmap.loose.find(t => t.status === 'in_progress')
  if (!hasPlan && !phaseMode && !tasksMode && !looseActive) return []

  const live = agents.length > 0 || milestoneStage(now, milestone ?? null) !== null
  const spin = agents.length > 0 ? SPINNER[Math.abs(tick) % SPINNER.length]! : '▶'
  const activeRow = roadmap.rows.find(r => r.state === 'active')

  const core: { kind: CoreKind; row: BandRow }[] = []
  const expired = phase?.closedAt != null && now - phase.closedAt > CLOSED_SHOW_MS
  if (phase && current && !expired) {
    const row = phaseRow({ phase, milestone: milestone ?? null, implDone: roadmap.done, implTotal: roadmap.total, width, tick, now, working: agents.length > 0 })
    if (row.length > 0) core.push({ kind: 'phases', row })
  }
  let mine: BandAgent[] = []
  let withoutTask: BandAgent[] = []
  let otherTask: BandAgent[] = []
  if (hasPlan) {
    const flashN = flash && now - flash.at >= 0 && now - flash.at < FLASH_MS ? flash.n : undefined
    const t = track(roadmap.rows, width, { tick, live, flashN })
    const complete = roadmap.total > 0 && roadmap.done === roadmap.total
    core.push({ kind: 'header', row: header({ title: input.title || 'Plan', repo: input.repo, right: progressRight(roadmap.done, roadmap.total), complete, width, tick, live }) })
    core.push({ kind: 'line', row: t.line })
    core.push({ kind: 'numbers', row: t.numbers })
    if (activeRow) {
      core.push({
        kind: 'active',
        row: [{ text: `${spin} `, color: CURRENT, bold: true }, { text: `${activeRow.n} ${truncate(activeRow.title, Math.max(1, width - 5))}`, bold: true }],
      })
    }
    mine = activeRow ? agents.filter(a => a.taskN === activeRow.n) : []
    withoutTask = agents.filter(a => a.taskN === undefined)
    otherTask = agents.filter(a => a.taskN !== undefined && a.taskN !== activeRow?.n)
  } else if (phaseMode && current) {
    // sin título: el worktree basta; sin repo, «Desarrollo» (la fase ya va a la derecha)
    const title = phase?.specTitle ?? (current === 'spec' ? 'Spec' : input.title || (input.repo ? '' : 'Desarrollo'))
    core.push({ kind: 'header', row: header({ title, repo: input.repo, right: [{ text: PHASE_LABEL[current], color: SOFT }], complete: false, width, tick, live }) })
    // sin plan: la task en curso o, si no hay, la primera pendiente
    const doing = pendingTasks.find(t => t.status === 'in_progress') ?? looseActive
    const shown = doing ?? pendingTasks[0]
    if (shown) core.push({ kind: 'active', row: looseRow(shown, doing !== undefined, spin, width) })
    mine = agents
  } else if (tasksMode) {
    const all = looseTasks ?? []
    const done = all.filter(t => t.status === 'completed').length
    core.push({ kind: 'header', row: header({ title: input.repo ? '' : 'Tasks', repo: input.repo, right: progressRight(done, all.length), complete: false, width, tick, live }) })
    const doing = pendingTasks.find(t => t.status === 'in_progress')
    const shown = doing ?? pendingTasks[0]!
    core.push({ kind: 'active', row: looseRow(shown, doing !== undefined, spin, width) })
    mine = agents
  } else if (looseActive) {
    core.push({
      kind: 'active',
      row: [{ text: `${spin} `, color: CURRENT, bold: true }, { text: truncate(looseActive.subject, Math.max(1, width - 2)), bold: true }],
    })
    mine = agents
  }

  // el alto manda: primero se sacrifican los números y la línea, luego las fases, nunca la cabecera
  // en la celebración, la fila de la Task activa pasa a ser «✦ ¡hito! <fase completada> ✔» (la fila de fases no se toca)
  if (milestone && milestoneStage(now, milestone)?.stage === 'celebrate' && (milestone.to === current || milestone.to === 'done')) {
    const row: BandRow = [{ text: truncate(`✦ ¡hito! ${PHASE_LABEL[milestone.from]} ✔`, width), color: ACCENT, bold: true }]
    const at = core.findIndex(c => c.kind === 'active')
    if (at >= 0) core[at] = { kind: 'active', row } // sin fila activa no se añade nada: el hueco animado es la celebración
  }

  let budget = maxRows
  let kept = core
  for (const drop of ['numbers', 'line', 'phases', 'active'] as const) {
    if (kept.length <= budget) break
    kept = kept.filter(c => c.kind !== drop)
  }
  kept = kept.slice(0, budget)
  budget -= kept.length

  const out: BandRow[] = kept.map(c => c.row)
  const total = mine.length + withoutTask.length + otherTask.length
  if (budget > 0 && total > 0) {
    let treeShow = mine.length > MAX_TREE ? MAX_TREE - 1 : mine.length
    const extra = (otherTask.length > 0 ? 1 : 0) + (withoutTask.length > 0 ? 1 : 0)
    const wanted = treeShow + (mine.length > treeShow ? 1 : 0) + extra
    let summary = mine.length - treeShow
    let tail: BandRow[] = []
    if (wanted > budget) {
      treeShow = Math.min(treeShow, budget - 1)
      summary = total - treeShow
    } else {
      if (withoutTask.length > 0) tail.push([{ text: `⚙ ${withoutTask.length} más (sin Task)`, dim: true }])
      if (otherTask.length > 0) tail.push([{ text: `⚙ ${otherTask.length} más (otra Task)`, dim: true }])
    }
    const rows: BandRow[] = []
    mine.slice(0, treeShow).forEach((a, i) => {
      const last = i === treeShow - 1 && summary <= 0
      rows.push(agentRow(last ? '  └─ ' : '  ├─ ', a, now, width, tick))
    })
    if (summary > 0) rows.push([{ text: `  └─ +${summary} más`, dim: true }])
    out.push(...rows, ...tail)
  }
  return out.slice(0, maxRows).map(r => fitRow(r, width))
}

