import type { Milestone } from '../../types'
import { PALETTE } from './palette'
import type { Seg } from './text'

/** Chispa de Claude: frames del giro (todos miden 1 columna, para no mover la fila de fases). */
export const SPARK = ['·', '✢', '✳', '✶', '✻', '✽']
export const SPARK_IDLE = '✻'
/** Hueco de la estación al celebrar: alterna estos frames (1 columna) con los colores de `sparkles`. */
export const CELEBRATE_FRAMES = ['✽', '✻', '✶', '✳']

export const WALK_MS = 1500
export const CELEBRATE_MS = 1000
export const MILESTONE_MS = 2500

/** Frame de giro de la chispa según el tick. */
export const sparkSpin = (tick: number): string => SPARK[Math.abs(Math.floor(tick)) % SPARK.length]!

/** Chispa en reposo: fija (✻) y, trabajando, gira con el tick. */
export function clawdIdle(tick: number, working: boolean): string {
  return working ? sparkSpin(tick) : SPARK_IDLE
}

export type MilestoneStage = { stage: 'walk'; progress: number } | { stage: 'celebrate' }

/** Tramo del hito en curso: camina (progreso 0..1), celebra, o null si ya pasó (o no hay hito). */
export function milestoneStage(now: number, m: Milestone | null): MilestoneStage | null {
  if (!m) return null
  const dt = Math.max(0, now - m.at)
  if (dt < WALK_MS) return { stage: 'walk', progress: dt / WALK_MS }
  if (dt < MILESTONE_MS) return { stage: 'celebrate' }
  return null
}

/** Frame de celebración del hueco y su color, según el tick. */
export function celebrateSpark(tick: number): Seg {
  const t = Math.abs(Math.floor(tick))
  return { text: CELEBRATE_FRAMES[t % CELEBRATE_FRAMES.length]!, color: PALETTE.sparkles[t % PALETTE.sparkles.length] }
}

/** Dos chispas que alternan ✦/✧ y rotan de color con el tick. */
export function sparkles(tick: number): [Seg, Seg] {
  const t = Math.abs(Math.floor(tick))
  const glyph = t % 2 === 0 ? '✦' : '✧'
  const n = PALETTE.sparkles.length
  return [
    { text: glyph, color: PALETTE.sparkles[t % n] },
    { text: glyph, color: PALETTE.sparkles[(t + 1) % n] },
  ]
}

