import type { Milestone, PhaseId, PhaseState } from '../../types'
import { celebrateSpark, clawdIdle, milestoneStage, sparkSpin } from './clawd'
import { PALETTE } from './palette'
import { fitRow, pulseOn, rowWidth } from './text'
import type { BandRow, Seg } from './text'

// Lógica pura de las fases del desarrollo (Spec → Plan → Implementación → Revisión → Cierre).

export const PHASES: PhaseId[] = ['spec', 'plan', 'impl', 'review', 'close']
export const PHASE_LABEL: Record<PhaseId, string> = {
  spec: 'Spec',
  plan: 'Plan',
  impl: 'Implementación',
  review: 'Revisión',
  close: 'Cierre',
}
export const PHASE_SHORT: Record<PhaseId, string> = { spec: 'Spec', plan: 'Plan', impl: 'Impl', review: 'Rev', close: 'Cierre' }

export const EMPTY_PHASE: PhaseState = { current: null, closedAt: null, source: null, specTitle: null }

export const SPEC_RE = /(^|\/)docs\/superpowers\/specs\/[^/]+\.md$/

/** Fase que abre una skill (con o sin prefijo `superpowers:`); null si no es de ninguna. */
export function phaseForSkill(skill: string): PhaseId | null {
  if (skill.includes('receiving-code-review')) return null
  if (skill.includes('brainstorming')) return 'spec'
  if (skill.includes('writing-plans')) return 'plan'
  if (skill.includes('subagent-driven-development') || skill.includes('executing-plans')) return 'impl'
  if (skill.includes('requesting-code-review') || skill.includes('code-review')) return 'review'
  if (skill.includes('finishing-a-development-branch')) return 'close'
  return null
}

// `git [-C ruta]… merge` (no merge-base ni --abort) o `gh pr create|merge`.
export const isCloseCommand = (cmd: string): boolean =>
  (/\bgit\s+(?:-C\s+\S+\s+)*merge(?![-\w])/.test(cmd) && !/--abort\b/.test(cmd)) || /\bgh\s+pr\s+(create|merge)\b/.test(cmd)

/**
 * Solo avanza; devuelve el mismo objeto si no cambia. Revisión y cierre no abren ciclo (ni desde cero ni tras cerrar).
 * Con `reopen` (lo abre una skill, no la lectura de un fichero), spec o plan desde implementación, revisión o
 * cierre abren un ciclo nuevo.
 */
export function advance(s: PhaseState, to: PhaseId, reopen = false): PhaseState {
  const opens = to !== 'review' && to !== 'close'
  if (s.closedAt !== null) return opens ? { ...EMPTY_PHASE, current: to } : s
  if (s.current === null) return opens ? { ...s, current: to } : s
  // otro spec o plan con la implementación ya en marcha: ciclo nuevo en la misma rama, sin merge entre medias
  if (reopen && (to === 'spec' || to === 'plan') && PHASES.indexOf(s.current) >= PHASES.indexOf('impl')) return { ...EMPTY_PHASE, current: to }
  if (PHASES.indexOf(s.current) < PHASES.indexOf(to)) return { ...s, current: to }
  return s
}

/** Texto del primer `# ` del documento, recortado. */
export function specTitleFrom(text: string): string | null {
  const m = /^# +(.+)$/m.exec(text)
  const t = m?.[1]?.trim()
  return t ? t : null
}

export type PhaseRowInput = {
  phase: PhaseState
  milestone: Milestone | null
  implDone: number
  implTotal: number
  width: number
  tick: number
  now: number
  working: boolean
}

const MIN_RUN = 2
const GAP = 1 // espacio a cada lado del tramo

/**
 * Fila de fases: estaciones con su conector. La maqueta (etiquetas y longitud de los tramos) es la del estado
 * de llegada y no depende de `tick`, de la etapa del hito ni de `working`: las animaciones se pintan encima
 * (hueco de 1 columna, icono que sustituye un carácter del tramo) sin cambiar ningún ancho.
 */
export function phaseRow(input: PhaseRowInput): BandRow {
  const { phase, milestone, implDone, implTotal, width, tick, now, working } = input
  if (phase.current === null) return []
  const cur = PHASES.indexOf(phase.current)
  const stage = milestone && (milestone.to === phase.current || milestone.to === 'done') ? milestoneStage(now, milestone) : null
  const toDone = !!milestone && milestone.to === 'done' && !!stage
  const allDone = phase.closedAt !== null || toDone
  const walk = !toDone && stage?.stage === 'walk' ? stage : null
  const celebrate = toDone || stage?.stage === 'celebrate'
  const digits = String(Math.max(0, implTotal)).length
  const counter = implTotal > 0 ? ` ${String(implDone).padStart(digits)}/${implTotal}` : ''
  const labelColor = pulseOn(tick) ? PALETTE.currentStrong : PALETTE.currentWeak
  const spin = sparkSpin(tick)
  // hueco de 1 columna: en blanco al caminar, destellos al celebrar, giro al trabajar, ✻ fijo en reposo
  const hole: Seg = walk ? { text: ' ' } : celebrate ? celebrateSpark(tick) : { text: clawdIdle(tick, working), color: PALETTE.clawd }
  const tail = (): BandRow => (allDone ? [{ text: ' ' }, hole, { text: ' 🎉' }] : [])

  const isDone = (i: number) => allDone || i < cur

  const station = (i: number, labels: Record<PhaseId, string>): BandRow => {
    const id = PHASES[i]!
    const label = labels[id]
    if (isDone(i)) return [{ text: `${label} ✔`, color: PALETTE.done }]
    if (i > cur) return [{ text: label, color: PALETTE.pending }]
    const text = id === 'impl' ? `${label}${counter}` : label
    return [hole, { text: ' ' }, { text, color: labelColor, bold: true }]
  }

  const run = (g: number, len: number): BandRow => {
    if (walk && g === cur - 1) {
      // el icono sustituye un carácter del tramo (no se inserta)
      const pos = Math.round(walk.progress * (len - 1))
      return [
        { text: '━'.repeat(pos), color: PALETTE.done },
        { text: spin, color: PALETTE.clawd },
        { text: '┄'.repeat(len - pos - 1), color: PALETTE.pending },
      ].filter(s => s.text)
    }
    return [isDone(g) ? { text: '━'.repeat(len), color: PALETTE.done } : { text: '┄'.repeat(len), color: PALETTE.pending }]
  }

  const build = (labels: Record<PhaseId, string>): BandRow | null => {
    const stations = PHASES.map((_, i) => station(i, labels))
    const end = tail()
    const gaps = PHASES.length - 1
    const fixed = stations.reduce((n, s) => n + rowWidth(s), 0) + rowWidth(end)
    const spare = width - fixed - gaps * (GAP * 2 + MIN_RUN)
    if (spare < 0) return null
    const out: BandRow = []
    stations.forEach((s, i) => {
      out.push(...s)
      if (i < gaps) {
        const len = MIN_RUN + Math.floor(spare / gaps) + (i < spare % gaps ? 1 : 0)
        out.push({ text: ' ' }, ...run(i, len), { text: ' ' })
      }
    })
    return [...out, ...end]
  }

  for (const labels of [PHASE_LABEL, PHASE_SHORT]) {
    const r = build(labels)
    if (r) return r
  }

  // una sola estación: «<hueco> Etiqueta [n/m] · fase i/5»
  const id = allDone ? 'close' : phase.current
  const idx = PHASES.indexOf(id)
  const label = PHASE_SHORT[id]
  const phaseTag: Seg = { text: ` · fase ${idx + 1}/${PHASES.length}`, dim: true }
  const head: BandRow = allDone
    ? [{ text: `${label} ✔`, color: PALETTE.done }, ...tail()]
    : [hole, { text: ' ' }, { text: label, color: labelColor, bold: true }]
  const withCounter: BandRow = [...head, ...(!allDone && id === 'impl' && counter ? [{ text: counter, color: labelColor, bold: true }] : []), phaseTag]
  if (rowWidth(withCounter) <= width) return withCounter
  return fitRow([...head, phaseTag], width)
}

