import type { Roadmap, RoadmapRow } from './taskMatcher'

export function progressBar(done: number, total: number, width = 12): string {
  const filled = total > 0 ? Math.round((done / total) * width) : 0
  return '█'.repeat(filled) + '░'.repeat(width - filled)
}

export function visibleRows(
  rows: RoadmapRow[],
  room: number,
): { rows: RoadmapRow[]; hiddenBefore: number; hiddenAfter: number } {
  if (rows.length <= room) return { rows, hiddenBefore: 0, hiddenAfter: 0 }
  let focus = rows.findIndex(x => x.state === 'active')
  if (focus < 0) focus = rows.findIndex(x => x.state === 'pending')
  if (focus < 0) focus = rows.length - 1
  const start = Math.max(0, Math.min(focus - Math.floor((room - 1) / 2), rows.length - room))
  return {
    rows: rows.slice(start, start + room),
    hiddenBefore: start,
    hiddenAfter: rows.length - start - room,
  }
}

