// Lógica pura del ledger de subagent-driven-development: <raíz>/.superpowers/sdd/<plan>/progress.md

const PLAN_PATH_RE = /^(.*)\/docs\/superpowers\/plans\/([^/]+)\.md$/

/** Ruta del ledger del plan; null si la ruta no tiene la forma `…/docs/superpowers/plans/<x>.md`. */
export function ledgerPath(planAbs: string): string | null {
  const m = PLAN_PATH_RE.exec(planAbs)
  return m ? `${m[1]}/.superpowers/sdd/${m[2]}/progress.md` : null
}

/** Números N de las líneas `Task N: complete`, sin duplicados y en orden de aparición. */
export function completedFromLedger(text: string): number[] {
  const out: number[] = []
  for (const line of text.split(/\r?\n/)) {
    const m = /^Task (\d+): complete\b/.exec(line)
    if (m) {
      const n = Number(m[1])
      if (!out.includes(n)) out.push(n)
    }
  }
  return out
}

/** ¿Menciona el ledger este comando Bash o es esta ruta del ledger (Write/Edit)? */
export const touchesLedgerCommand = (cmd: string): boolean => cmd.includes('progress.md')
export const isLedgerFile = (p: string): boolean => /\/\.superpowers\/sdd\/[^/]+\/progress\.md$/.test(p)

