// Helpers puros: el motor solo sigue `$` y los átomos dentro de register.tsx.

export const PLAN_RE = /(^|\/)docs\/superpowers\/plans\/[^/]+\.md$/

export const storeKey = (path: string) => `done:${path}`

/** Ruta absoluta a partir del cwd (pura: `$` no puede cruzar imports). */
export function absolutePath(cwd: string, path: string): string {
  if (path.startsWith('/')) return path
  return `${cwd.replace(/\/$/, '')}/${path.replace(/^\.\//, '')}`
}

/** Carpeta que contiene el plan (dirname puro). */
export function planDir(abs: string): string {
  const i = abs.lastIndexOf('/')
  return i > 0 ? abs.slice(0, i) : '/'
}

/** Worktree (basename del toplevel) y rama; HEAD desacoplado -> `HEAD@<sha>`. Null si falta algo. */
export function repoFromGit(top: string, branch: string, sha: string): { worktree: string; branch: string } | null {
  const worktree = top.trim().replace(/\/+$/, '').split('/').pop() ?? ''
  const name = branch.trim() || (sha.trim() ? `HEAD@${sha.trim()}` : '')
  return worktree && name ? { worktree, branch: name } : null
}

// Rutas sin comillas, espacios, `$` ni separadores de shell; el `=` corta asignaciones (`P=docs/…`).
const PLAN_IN_CMD = /([^\s'"=;|&<>()$]*?)docs\/superpowers\/plans\/([^\s'"=;|&<>()$/]+\.md)/g
const LEDGER_IN_CMD = /([^\s'"=;|&<>()$]*?)\.superpowers\/sdd\/([^\s'"=;|&<>()$/]+)/g

/** Planes que nombra un comando Bash: por su ruta o por la carpeta de su ledger SDD. Sin duplicados. */
export function planRefsInCommand(cmd: string): string[] {
  const out: string[] = []
  const push = (p: string) => {
    if (!out.includes(p)) out.push(p)
  }
  for (const m of cmd.matchAll(PLAN_IN_CMD)) push(`${m[1]}docs/superpowers/plans/${m[2]}`)
  for (const m of cmd.matchAll(LEDGER_IN_CMD)) push(`${m[1]}docs/superpowers/plans/${m[2]}.md`)
  return out
}

/** Directorio de un `cd` al principio del comando; null si no empieza así. */
export function cdTarget(cmd: string): string | null {
  const m = /^\s*cd\s+(?:"([^"]+)"|'([^']+)'|([^\s;&|]+))/.exec(cmd)
  return m ? (m[1] ?? m[2] ?? m[3] ?? null) : null
}

/** Raíz del repo que contiene `docs/superpowers/…`; null si la ruta no tiene esa forma. */
export function repoRoot(abs: string | null): string | null {
  const m = abs ? /^(.*)\/docs\/superpowers\//.exec(abs) : null
  return m ? m[1]! || '/' : null
}

