// Primitivas de texto compartidas por la franja y las fases: puras, sin `$` ni estado.

export type Seg = { text: string; color?: string; bold?: boolean; dim?: boolean }
export type BandRow = Seg[]

// Puntos de 0x2300–0x2BFF con East Asian Width=W (presentación emoji); el resto de ese bloque mide 1.
const WIDE_SYMBOLS = new Set<number>([0x231a, 0x231b, 0x25fd, 0x25fe, 0x2614, 0x2615, 0x267f, 0x2693, 0x26a1, 0x26aa, 0x26ab, 0x26bd, 0x26be, 0x26c4, 0x26c5, 0x26ce, 0x26d4, 0x26ea, 0x26f2, 0x26f3, 0x26f5, 0x26fa, 0x26fd, 0x2705, 0x270a, 0x270b, 0x2728, 0x274c, 0x274e, 0x2757, 0x27b0, 0x27bf, 0x2b1b, 0x2b1c, 0x2b50, 0x2b55])
const isWideSymbol = (cp: number) =>
  WIDE_SYMBOLS.has(cp) || (cp >= 0x23e9 && cp <= 0x23ec) || cp === 0x23f0 || cp === 0x23f3 || (cp >= 0x2648 && cp <= 0x2653) || (cp >= 0x2753 && cp <= 0x2755) || (cp >= 0x2795 && cp <= 0x2797)

/** Columnas que ocupa un texto, según East Asian Width (wcwidth): emojis y CJK 2; ✔ ✻ ⚙ y demás símbolos 1. */
export function cellWidth(s: string): number {
  let w = 0
  for (const ch of s) {
    const cp = ch.codePointAt(0) ?? 0
    if (cp === 0xfe0f || cp === 0x200d) continue
    const wide =
      cp >= 0x1f000 ||
      isWideSymbol(cp) ||
      (cp >= 0x1100 && cp <= 0x115f) ||
      (cp >= 0x2e80 && cp <= 0xa4cf) ||
      (cp >= 0xac00 && cp <= 0xd7a3) ||
      (cp >= 0xff00 && cp <= 0xff60)
    w += wide ? 2 : 1
  }
  return w
}

export function truncate(s: string, max: number): string {
  if (max <= 0) return ''
  if (cellWidth(s) <= max) return s
  let out = ''
  let w = 0
  for (const ch of s) {
    const cw = cellWidth(ch)
    if (w + cw > max - 1) break
    out += ch
    w += cw
  }
  return `${out}…`
}

export const rowWidth = (r: BandRow) => r.reduce((n, s) => n + cellWidth(s.text), 0)

/** Recorta una fila a `max` columnas (último recurso: ninguna fila excede el ancho). */
export function fitRow(r: BandRow, max: number): BandRow {
  if (rowWidth(r) <= max) return r
  const out: BandRow = []
  let left = max
  for (const s of r) {
    if (left <= 0) break
    const w = cellWidth(s.text)
    if (w <= left) {
      out.push(s)
      left -= w
    } else {
      out.push({ ...s, text: truncate(s.text, left) })
      left = 0
    }
  }
  return out
}

/** Pulso de la estación actual: alterna cada 2 ticks (fuerte, tenue). */
export const pulseOn = (tick: number) => Math.floor(Math.abs(tick) / 2) % 2 === 0

