  model: string
  background: boolean
  /** Id del subagente (resultado de agent.spawn); casa con $.agent.list(). */
  agentId?: string
  /** Instante de arranque (ms, `$.clock.now()`), para el tiempo transcurrido. */
  startedAt?: number
  /** Task del plan activo que menciona la descripción («… Task 8 …»). */
  taskN?: number
}

export type PhaseId = 'spec' | 'plan' | 'impl' | 'review' | 'close'
export type PhaseState = {
  /** Fase en curso; null: no hay desarrollo en marcha. */
  current: PhaseId | null
  /** Instante (ms) en que se completó el Cierre; null si no. */
  closedAt: number | null
  /** Ruta absoluta del spec o plan que abrió el ciclo. */
  source: string | null
  /** Título del spec (primer `# `), para la cabecera antes del plan. */
  specTitle: string | null
}
/** Paso de un hito: de una fase a la siguiente, o 'done' al completar el Cierre. */
export type Milestone = { from: PhaseId; to: PhaseId | 'done'; at: number }
/** Destello de la estación de una Task recién completada. */
export type TaskFlash = { n: number; at: number }

declare module 'claude-code' {
  interface PluginState {
    roadmap: {
      tasks: SessionTask[]
      todos: SessionTask[]
      agents: ActiveAgent[]
      planPath: string | null
      pinned: boolean
      plan: Plan | null
      planError: string | null
      doneStored: number[]
      isOpen: boolean
      storeOk: boolean
      tick: number
      bandHidden: boolean
      phase: PhaseState
      milestone: Milestone | null
      flash: TaskFlash | null
      /** Worktree y rama donde vive el plan activo (git -C <carpeta del plan>); null si no se pudo leer. */
      repo: { worktree: string; branch: string } | null
    }
  }
}
